// src/components/ai/SpeechSynthesis.js
// 100% FREE Web Speech Synthesis API - Text-to-Speech

export class SpeechSynthesisEngine {
  constructor() {
    this.synthesis = window.speechSynthesis;
    this.voice = null;
    this.isSpeaking = false;
  }

  initialize() {
    if (!this.synthesis) {
      console.error('Speech Synthesis not supported');
      return false;
    }

    // Load voices
    return new Promise((resolve) => {
      const loadVoices = () => {
        const voices = this.synthesis.getVoices();

        // Try to find a good English voice
        this.voice = voices.find(v => v.lang.startsWith('en-') && v.name.includes('Google')) ||
                     voices.find(v => v.lang.startsWith('en-US')) ||
                     voices.find(v => v.lang.startsWith('en')) ||
                     voices[0];

        if (this.voice) {
          console.log('Selected voice:', this.voice.name);
          resolve(true);
        } else {
          resolve(false);
        }
      };

      // Voices might not be loaded immediately
      if (this.synthesis.getVoices().length > 0) {
        loadVoices();
      } else {
        this.synthesis.onvoiceschanged = loadVoices;
      }
    });
  }

  speak(text, options = {}) {
    return new Promise((resolve, reject) => {
      if (!this.synthesis) {
        reject(new Error('Speech Synthesis not supported'));
        return;
      }

      // Cancel any ongoing speech
      this.synthesis.cancel();

      const utterance = new SpeechSynthesisUtterance(text);

      // Set voice
      if (this.voice) {
        utterance.voice = this.voice;
      }

      // Set parameters
      utterance.rate = options.rate || 0.9; // Slightly slower for clarity
      utterance.pitch = options.pitch || 1.0;
      utterance.volume = options.volume || 1.0;

      utterance.onstart = () => {
        this.isSpeaking = true;
        if (options.onStart) options.onStart();
      };

      utterance.onend = () => {
        this.isSpeaking = false;
        if (options.onEnd) options.onEnd();
        resolve();
      };

      utterance.onerror = (error) => {
        this.isSpeaking = false;
        if (options.onError) options.onError(error);
        reject(error);
      };

      this.synthesis.speak(utterance);
    });
  }

  stop() {
    if (this.synthesis) {
      this.synthesis.cancel();
      this.isSpeaking = false;
    }
  }

  pause() {
    if (this.synthesis) {
      this.synthesis.pause();
    }
  }

  resume() {
    if (this.synthesis) {
      this.synthesis.resume();
    }
  }

  isSupported() {
    return !!window.speechSynthesis;
  }

  getSpeaking() {
    return this.isSpeaking;
  }
}
